# >>> STATIC
_static_ask_for_approval() {
    cat <<-'ARGCEOF'
	on-request	The model decides when to ask the user for approval
	never	Never ask for user approval Execution failures are immediately returned to the model
ARGCEOF
}

_static_resume_ask_for_approval() {
    cat <<-'ARGCEOF'
	on-request	The model decides when to ask the user for approval
	never	Never ask for user approval Execution failures are immediately returned to the model
ARGCEOF
}

_static_fork_ask_for_approval() {
    cat <<-'ARGCEOF'
	on-request	The model decides when to ask the user for approval
	never	Never ask for user approval Execution failures are immediately returned to the model
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_feature() {
    local want=""
    case "${argc__option:-}" in
    argc_enable) want=false ;;
    argc_disable) want=true ;;
    esac
    codex features list 2>/dev/null | gawk -v want="$want" 'NF >= 3 && (want == "" || $3 == want) { printf "%s\t%s %s\n", $1, $2, $3 }'
}

_choice_git_branch() {
    command -v git >/dev/null 2>&1 || return 0
    git for-each-ref --count=500 --format='%(refname:strip=2)%09%(subject)' refs/heads refs/remotes 2>/dev/null
}

_choice_git_commit() {
    command -v git >/dev/null 2>&1 || return 0
    git log --all --max-count=200 --format='%h%x09%s' 2>/dev/null
}

_choice_local_provider() {
    printf '%s\n' lmstudio ollama
}

_choice_marketplace() {
    codex plugin marketplace list --json 2>/dev/null | jq -b -r '.marketplaces[] | "\(.name)\t\(.marketplaceSource.source // .root // "")"'
}

_choice_mcp_name() {
    codex mcp list --json 2>/dev/null | jq -b -r '.[] | "\(.name)\t\(.transport.command // .transport.type // "")"'
}

_choice_model() {
    codex debug models --bundled 2>/dev/null | jq -b -r '.models[] | select(.visibility == "list") | "\(.slug)\t\(.display_name)"'
}

_choice_plugin_available() {
    codex plugin list --available --json 2>/dev/null | jq -b -r '.available[] | "\(.pluginId)\t\(.version // "")"'
}

_choice_plugin_installed() {
    codex plugin list --json 2>/dev/null | jq -b -r '.installed[] | "\(.pluginId)\t\(.version // "")"'
}

_choice_profile() {
    local dir="${CODEX_HOME:-$HOME/.codex}" file
    for file in "$dir"/*.config.toml; do
        [[ -f "$file" ]] || continue
        file=${file##*/}
        printf '%s\n' "${file%.config.toml}"
    done
}

_choice_session() {
    local file="${CODEX_HOME:-$HOME/.codex}/session_index.jsonl"
    [[ -f "$file" ]] || return 0
    jq -b -r 'select(.id != null) | "\(.id)\t\((.thread_name // "") | gsub("\t"; " "))"' "$file" 2>/dev/null
}

_choice_task() {
    _argc_util_cache 300 _choice_task_uncached codex_cloud_tasks
}

_choice_task_uncached() {
    codex cloud list --json 2>/dev/null | jq -b -r '.tasks[] | select(.id != null) | "\(.id)\t\(.title // "")"'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
